const std = @import("std");

const PageAllocator = struct {
    pages: [][]u8,
    page_count: usize,

    fn alloc(self: *PageAllocator, size: usize) ?[]u8 {
        const page = std.posix.mmap(
            null,
            size,
            std.posix.PROT.READ | std.posix.PROT.WRITE,
            .{ .TYPE = .PRIVATE, .ANONYMOUS = true },
            -1,
            0,
        ) catch return null;
        return page[0..size];
    }

    fn dealloc(self: *PageAllocator, ptr: []u8) void {
        std.posix.munmap(ptr);
    }
};

pub fn main() !void {
    var alloc = PageAllocator{ .pages = undefined, .page_count = 0 };
    const mem = (alloc.alloc(256) orelse return);
    defer alloc.dealloc(mem);

    @memcpy(mem, "Custom allocator works!");
    std.debug.print("{s}\n", .{mem[0..22]});
}

